use std::collections::BTreeMap;

use super::*;
use crate::color::parse;

type Snapshot = BTreeMap<String, Variants>;

#[derive(serde::Deserialize)]
struct Variants {
    solid: BTreeMap<String, String>,
    glass: BTreeMap<String, String>,
}

fn snapshot() -> Snapshot {
    serde_json::from_str(include_str!("../data/tokens.snapshot.json")).expect("snapshot is valid")
}

/// Every token `buildTokens` / `glassTokens` write in TypeScript is produced here with
/// the same value, for every theme, solid and glass. The snapshot is regenerated by
/// `node native/scripts/export-themes.mjs`; a theme edited on one side only fails here.
#[test]
fn tokens_match_the_typescript_snapshot() {
    let snap = snapshot();
    assert_eq!(snap.len(), 24);
    let mut checked = 0;
    for id in all_ids() {
        let seed = seed(id).unwrap();
        let variants = &snap[id];
        for (label, expected, ours) in [
            ("solid", &variants.solid, Tokens::solid(seed)),
            ("glass", &variants.glass, Tokens::glass(seed)),
        ] {
            for (name, css) in expected {
                let token = Token::from_css_name(name)
                    .unwrap_or_else(|| panic!("{id}: unknown token {name}"));
                let want = parse(css).unwrap_or_else(|e| panic!("{id}/{name}: {e}"));
                let got = ours
                    .get(token)
                    .unwrap_or_else(|| panic!("{id}/{label}: {name} missing"));
                assert!(
                    got.close_to(&want, 1),
                    "{id}/{label}/{name}: ours {got} vs TS {css}"
                );
                checked += 1;
            }
        }
    }
    assert!(checked > 1300, "only {checked} tokens compared");
}

/// Glass writes a subset on top of the solid set; every other token must be left as it was,
/// and a solid set never carries the glass-only ones.
#[test]
fn glass_only_tokens_are_absent_when_solid() {
    for id in all_ids() {
        let seed = seed(id).unwrap();
        let solid = Tokens::solid(seed);
        let glass = Tokens::glass(seed);
        for token in Token::ALL {
            let glass_only = token.css_name().starts_with("glass-");
            assert_eq!(
                solid.get(*token).is_none(),
                glass_only,
                "{id}/{}",
                token.css_name()
            );
            assert!(glass.get(*token).is_some(), "{id}/{}", token.css_name());
        }
    }
}

#[test]
fn catalogue_has_twelve_of_each_kind() {
    assert_eq!(ids_for(ThemeKind::Light).len(), 12);
    assert_eq!(ids_for(ThemeKind::Dark).len(), 12);
    for kind in [ThemeKind::Light, ThemeKind::Dark] {
        for id in ids_for(kind) {
            assert_eq!(super::seed(id).unwrap().kind, kind, "{id}");
        }
    }
}

#[test]
fn system_mode_follows_the_os_and_unknown_ids_fall_back() {
    let prefs = Preferences {
        dark_theme: "no-such-theme".into(),
        ..Preferences::default()
    };
    assert_eq!(prefs.resolve(true, false).id, DEFAULT_DARK_THEME);
    assert_eq!(prefs.resolve(false, false).id, DEFAULT_LIGHT_THEME);
    let forced = Preferences {
        mode: ThemeMode::Dark,
        ..Preferences::default()
    };
    assert_eq!(forced.resolve(false, false).kind, ThemeKind::Dark);
}

#[test]
fn glass_needs_a_blur_to_show() {
    let prefs = Preferences::default();
    assert!(
        prefs
            .resolve(true, true)
            .tokens
            .get(Token::GlassPane)
            .is_some()
    );
    assert!(
        prefs
            .resolve(true, false)
            .tokens
            .get(Token::GlassPane)
            .is_none()
    );
    let off = Preferences {
        glass: false,
        ..Preferences::default()
    };
    assert!(
        off.resolve(true, true)
            .tokens
            .get(Token::GlassPane)
            .is_none()
    );
}

#[test]
fn font_size_is_clamped_to_the_pickers_range() {
    assert_eq!(clamp_ui_font_size(8.0), UI_FONT_SIZE_MIN);
    assert_eq!(clamp_ui_font_size(99.0), UI_FONT_SIZE_MAX);
    assert_eq!(clamp_ui_font_size(15.4), 15.0);
}
